// Browser regression tests for how native hosts serve the editor page
// (issue #43): boots the REAL bundled Monaco and the REAL bridge, in pages
// generated by the package's own builders, in headless Chrome - the
// Chromium engine behind WebView2 - and checks the features that depend on
// Monaco's web workers.
//
// Run from the package root (after `flutter pub get`):
//   node --test tool/browser_tests/
//
// Needs `dart` on PATH (or DART) and Google Chrome (or FLUTTER_MONACO_CHROME
// pointing at a Chrome/Chromium binary).
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, test } from 'node:test';
import url from 'node:url';

import { launchChrome } from './chrome.mjs';

const repoRoot = path.resolve(path.dirname(url.fileURLToPath(import.meta.url)), '..', '..');

// Stands in for the host: webview_flutter's JavaScriptChannel and WebView2's
// chrome.webview both deliver the bridge's messages here. Worker
// construction is counted to tell real workers from the main-thread
// fallback.
const HOST_STUB = `
  (function () {
    var harness = (window.__harness = { inbox: [], workers: 0 });
    var receive = function (message) {
      try { harness.inbox.push(JSON.parse(message)); } catch (_) {}
    };
    window.flutterChannel = { postMessage: receive };
    window.chrome = window.chrome || {};
    window.chrome.webview = { postMessage: receive };
    var NativeWorker = window.Worker;
    window.Worker = function (scriptUrl, options) {
      harness.workers++;
      return new NativeWorker(scriptUrl, options);
    };
    window.Worker.prototype = NativeWorker.prototype;
  })();
`;

const DIFF_BOOT = {
  mode: 'diff',
  original: 'a\nb\nc\n',
  modified: 'a\nB\nc\nd\n',
  language: 'plaintext',
  theme: 'vs',
  options: {},
};

// Line 2 changed, line 4 added.
const EXPECTED_LINE_CHANGES = [
  [2, 2, 2, 2],
  [3, 0, 4, 4],
];

const JSON_BOOT = { text: '{ "a": 1, }', language: 'json', theme: 'vs', options: {} };

const STEP_TIMEOUT_MS = 20000;
const TEST_TIMEOUT_MS = 90000;

let workDir;
let report;
let chrome;
let virtualHostRequests;

/** Lays out the cache under a path with an apostrophe (a profile such as O'Brien). */
function generatePages() {
  workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'fm-browser-tests-'));
  const cacheRoot = path.join(workDir, "Bob's Editor", 'monaco_editor_cache');
  const reportPath = path.join(workDir, 'pages.json');
  execFileSync(
    process.env.DART || 'dart',
    ['run', 'tool/browser_tests/generate_pages.dart', cacheRoot, reportPath],
    {
      cwd: repoRoot,
      stdio: ['ignore', 'ignore', 'inherit'],
      timeout: 300000,
      shell: process.platform === 'win32',
    },
  );
  report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));
  report.cacheRoot = cacheRoot;
}

/** The page's terminal boot lifecycle ('ready', or 'fatal: <error>'), or null. */
const lifecycleExpression = `(function () {
  var m = window.__harness.inbox.find(function (m) {
    return m.kind === 'lifecycle' && (m.name === 'ready' || m.name === 'fatal');
  });
  return m ? m.name + (m.error ? ': ' + JSON.stringify(m.error) : '') : null;
})()`;

let requestSeq = 0;

/** Sends a command through the real bridge and returns its result. */
async function invoke(page, method, params = {}) {
  const id = `h${++requestSeq}`;
  await page.evaluate(
    `window.FlutterMonaco.dispatch(${JSON.stringify({ id, method, params })}), true`,
  );
  const response = await page.waitFor(
    `window.__harness.inbox.find(function (m) { return m.kind === 'response' && m.id === ${JSON.stringify(id)}; })`,
    { timeoutMs: STEP_TIMEOUT_MS, what: `the ${method} response` },
  );
  assert.ok(response.ok, `${method} failed: ${JSON.stringify(response.error)}`);
  return response.value;
}

/** Opens [pageUrl] and boots the editor the way the Dart side does. */
async function bootEditor(pageUrl, bootParams) {
  const page = await chrome.newPage({ initScript: HOST_STUB });
  await page.navigate(pageUrl);
  await page.waitFor(
    `window.__harness.inbox.some(function (m) { return m.kind === 'lifecycle' && m.name === 'pageReady'; })`,
    { timeoutMs: STEP_TIMEOUT_MS, what: 'lifecycle pageReady' },
  );
  await page.evaluate(
    `window.FlutterMonaco.dispatch(${JSON.stringify({ id: 'boot', method: 'page.boot', params: bootParams })}), true`,
  );
  await page.waitFor(lifecycleExpression, {
    timeoutMs: STEP_TIMEOUT_MS,
    what: 'lifecycle ready',
  });
  assert.equal(await page.evaluate(lifecycleExpression), 'ready');
  return page;
}

/** The diff the bridge reports, polled until Monaco computed it. */
async function computedLineChanges(page) {
  const deadline = Date.now() + STEP_TIMEOUT_MS;
  for (;;) {
    // diff.getState itself waits up to 3s for Monaco's diff.
    const state = await invoke(page, 'diff.getState');
    if (state.lineChangeCount !== null) break;
    if (Date.now() > deadline) return null;
  }
  return page.evaluate(`window.diffEditor.getLineChanges().map(function (c) {
    return [c.originalStartLineNumber, c.originalEndLineNumber,
            c.modifiedStartLineNumber, c.modifiedEndLineNumber];
  })`);
}

/**
 * Asks the JSON language service to validate the document, through Monaco's
 * public worker accessor: 'answered', 'failed: <error name>', or 'hung'
 * when it does not settle within 10s (the issue #43 failure).
 */
function jsonServiceOutcome(page) {
  return page.evaluate(`(function () {
    var model = monaco.editor.getEditors()[0].getModel();
    var request = monaco.languages.json.getWorker()
      .then(function (getWorker) { return getWorker(model.uri); })
      .then(function (worker) { return worker.doValidation(model.uri.toString()); })
      .then(function () { return 'answered'; },
            function (e) { return 'failed: ' + (e && e.name); });
    var timeout = new Promise(function (resolve) {
      setTimeout(function () { resolve('hung'); }, 10000);
    });
    return Promise.race([request, timeout]);
  })()`);
}

function workerMode(page) {
  return page.evaluate('window.__FM_WORKERS ? window.__FM_WORKERS.mode : null');
}

function workerCount(page) {
  return page.evaluate('window.__harness.workers');
}

/** Monaco asked for a worker before the probe answered (the gate failed). */
function refusedWhileProbing(page) {
  return page.console.some((line) => line.includes('the worker check has not finished'));
}

before(async () => {
  generatePages();
}, { timeout: 300000 });

after(() => {
  if (workDir) fs.rmSync(workDir, { recursive: true, force: true });
});

describe('Windows: page served by the WebView2 virtual host', () => {
  before(async () => {
    chrome = await launchChrome();
    virtualHostRequests = await chrome.mapVirtualHost(report.virtualHost, report.cacheRoot);
  });
  after(async () => {
    await chrome.close();
  });

  test('computes the diff with a real worker', { timeout: TEST_TIMEOUT_MS }, async () => {
    const page = await bootEditor(report.pages.virtualHost.url, DIFF_BOOT);
    assert.equal(await page.evaluate('location.origin'), `https://${report.virtualHost}`);
    assert.deepEqual(await computedLineChanges(page), EXPECTED_LINE_CHANGES);
    assert.equal(await workerMode(page), null, 'no safety net on an https page');
    assert.ok((await workerCount(page)) >= 1, 'the editor worker ran in a worker');
    assert.deepEqual(page.exceptions, []);
    await page.close();
  });

  test('reports JSON diagnostics from the language worker', { timeout: TEST_TIMEOUT_MS }, async () => {
    const page = await bootEditor(report.pages.virtualHost.url, JSON_BOOT);
    await page.waitFor(
      `monaco.editor.getModelMarkers({}).some(function (m) { return m.message === 'Trailing comma'; })`,
      { timeoutMs: STEP_TIMEOUT_MS, what: 'JSON diagnostics' },
    );
    assert.equal(await jsonServiceOutcome(page), 'answered');
    assert.ok((await workerCount(page)) >= 2, 'editor and JSON workers ran');
    assert.deepEqual(page.exceptions, []);
    await page.close();
  });

  test('loads versioned assets and fingerprinted bridge scripts', () => {
    const prefix = `https://${report.virtualHost}/monaco-${report.monacoVersion}/`;
    // The browser asks for /favicon.ico on its own; the page never does.
    const pageRequests = virtualHostRequests.filter((r) => !r.endsWith('/favicon.ico'));
    assert.ok(pageRequests.length > 0);
    for (const request of pageRequests) {
      assert.ok(request.startsWith(prefix), request);
    }
    const bridge = pageRequests.filter((r) => r.includes('/bridge/'));
    assert.ok(bridge.length >= 7, 'every bridge script came from the virtual host');
    for (const request of bridge) {
      assert.match(request, /\.js\?v=[0-9a-f]{16}$/);
    }
    // The JSON worker's importScripts went through the virtual host too.
    assert.ok(pageRequests.some((r) => r.includes('/min/vs/assets/json.worker-')));
  });
});

describe('file:// page where workers cannot load scripts (WebView2, Chromium)', () => {
  before(async () => {
    chrome = await launchChrome();
  });
  after(async () => {
    await chrome.close();
  });

  for (const flavor of ['windowsFile', 'file']) {
    test(`${flavor}: the diff falls back to the main thread`, { timeout: TEST_TIMEOUT_MS }, async () => {
      const page = await bootEditor(report.pages[flavor].url, DIFF_BOOT);
      assert.deepEqual(await computedLineChanges(page), EXPECTED_LINE_CHANGES);
      assert.equal(await workerMode(page), 'main-thread');
      assert.equal(refusedWhileProbing(page), false);
      // Only the capability probe: Monaco never started a worker that hangs.
      assert.equal(await workerCount(page), 1);
      assert.deepEqual(page.exceptions, []);
      await page.close();
    });

    test(`${flavor}: language services fail fast instead of hanging`, { timeout: TEST_TIMEOUT_MS }, async () => {
      const page = await bootEditor(report.pages[flavor].url, JSON_BOOT);
      // Refused at once with Monaco's cancellation, not left pending.
      assert.equal(await jsonServiceOutcome(page), 'failed: Canceled');
      await page.evaluate(`monaco.editor.getEditors()[0].getModel().setValue('{ "b": 2, }'), true`);
      await new Promise((resolve) => setTimeout(resolve, 1500));
      assert.equal(await workerMode(page), 'main-thread');
      assert.equal(refusedWhileProbing(page), false);
      assert.equal(await workerCount(page), 1);
      // Monaco's validation scheduler surfaces the refusal as a canceled
      // request; nothing else may escape.
      for (const exception of page.exceptions) {
        assert.match(exception, /^Canceled: Canceled/);
      }
      await page.close();
    });
  }
});

describe('file:// page where workers can load scripts (Android WebView, WKWebView)', () => {
  before(async () => {
    // Lets a file: page's blob: workers importScripts file: URLs, as the
    // Android and Apple WebViews do.
    chrome = await launchChrome({ extraArgs: ['--allow-file-access-from-files'] });
  });
  after(async () => {
    await chrome.close();
  });

  test('keeps Monaco on its real workers', { timeout: TEST_TIMEOUT_MS }, async () => {
    const page = await bootEditor(report.pages.file.url, JSON_BOOT);
    await page.waitFor(
      `monaco.editor.getModelMarkers({}).some(function (m) { return m.message === 'Trailing comma'; })`,
      { timeoutMs: STEP_TIMEOUT_MS, what: 'JSON diagnostics' },
    );
    assert.equal(await jsonServiceOutcome(page), 'answered');
    assert.equal(await workerMode(page), 'workers');
    assert.equal(refusedWhileProbing(page), false);
    // The probe, the editor worker and the JSON worker.
    assert.ok((await workerCount(page)) >= 3);
    assert.deepEqual(page.exceptions, []);
    await page.close();
  });

  test('computes the diff with a real worker', { timeout: TEST_TIMEOUT_MS }, async () => {
    const page = await bootEditor(report.pages.file.url, DIFF_BOOT);
    assert.deepEqual(await computedLineChanges(page), EXPECTED_LINE_CHANGES);
    assert.equal(await workerMode(page), 'workers');
    assert.equal(refusedWhileProbing(page), false);
    assert.ok((await workerCount(page)) >= 2);
    assert.deepEqual(page.exceptions, []);
    await page.close();
  });
});
